mapper.select:
select t.car_num,t.car_num carNum,t.ps_id,t.ps_id psId,t.remark,t.status_cd,t.status_cd
statusCd,t.owner_id,t.owner_id ownerId,t.car_type_cd,t.car_type_cd carTypeCd,t.car_id,t.car_id
carId,t.lease_type,t.lease_type leaseType,t.car_type,t.car_type carType,t.start_time,t.start_time
startTime,t.end_time,t.end_time endTime,t.state,t.community_id,t.community_id
communityId,t.member_id,t.member_id memberId
from owner_car t
left join parking_space ps on t.ps_id = ps.ps_id and ps.status_cd = '0'
where 1 =1

    and ps.pa_id in

        #{item}




    and t.car_num= #{carNum}


    and t.ps_id= #{psId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.owner_id= #{ownerId}


    and t.car_type_cd= #{carTypeCd}


    and t.car_id= #{carId}


    and t.lease_type= #{leaseType}


    and t.car_type= #{carType}


    and t.start_time= #{startTime}


    and t.end_time= #{endTime}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.member_id= #{memberId}

order by t.create_time desc

    limit #{page}, #{row}

